function latestOccurrence(rule: RecurringIssue, now: Date): string | null {
  const parts = new Intl.DateTimeFormat(\"en-US\", {
    timeZone: rule.timezone, year: \"numeric\", month: \"2-digit\", day: \"2-digit\",
  }).formatToParts(now);
  const part = (name: string) => parts.find((p) => p.type === name)"'!.value;
  let day = `${part("year")}-${part("month")}-${part("day")}`;
  if (rule.cadence === "weekly") {
    const date = new Date(`${day}T00:00:00.000Z`);
    const weekday = date.getUTCDay() || 7;
    date.setUTCDate(date.getUTCDate() - (weekday - rule.weekday! + 7) % 7);
    day = date.toISOString().slice(0, 10);
  }
  return day >= rule.startsOn ? day : null;
}

export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    for (const rule of await rules.listActiveRecurringIssues()) {
      try {
        const occurrence = latestOccurrence(rule, now);
        if (occurrence === null || (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn)) continue;
        const project = await projects.findProjectById(rule.orgId, rule.projectId);
        if (!project || project.archivedAt !== null) continue;
        const creator = await members.findMember(rule.orgId, rule.createdBy);
        const actor: Actor | null = creator?.status === "active"
          ? { orgId: rule.orgId, userId: rule.createdBy, role: creator.role } : null;
        if (!actor || !can(actor, "issue:create", projectResource(project))) {
          await rules.updateRecurringIssue(rule.orgId, rule.id, { paused: true });
          continue;
        }
        const assignee = rule.assigneeId === null ? null : await members.findMember(rule.orgId, rule.assigneeId);
        await createIssue(actor, createIssueSchema.parse({
          orgId: rule.orgId, projectId: rule.projectId,
          title: `${rule.title} (${occurrence})`, priority: rule.priority,
          assigneeId: assignee?.status === "active" ? rule.assigneeId : null,
        }));
        await rules.updateRecurringIssue(rule.orgId, rule.id, { lastOccurrenceOn: occurrence });
        result.processed += 1;
      } catch {
